// English text reader for puhuja: words -> phonemes -> Synth.
//
// Pronunciation: letter-to-sound rules learned from CMUdict give a candidate
// for every word; for words where that candidate is wrong, a short edit
// script (stored per word) turns it into the dictionary pronunciation.
// Both tables are generated by tools/english_build.py (english_data.inc).
#ifndef PUHUJA_ENGLISH_H_
#define PUHUJA_ENGLISH_H_

#include <cstdint>
#include <deque>
#include <string>
#include <string_view>
#include <vector>

#include "puhuja.h"

namespace puhuja {

// ARPAbet-style tokens ("K", "AH0", ...), as in CMUdict.
std::vector<std::string> englishRules(std::string_view word);       // rules only
std::vector<std::string> englishPronounce(std::string_view word);   // rules + edits

// Streams English text into a Synth, one phrase at a time (up to , ; : . ! ?
// or a line break): words are pronounced, numbers read out, and the phrase
// gets an intonation (accents on content words, declination, a final fall,
// a rise for questions, a small rise before a comma).
class EnglishReader {
 public:
  explicit EnglishReader(Synth& synth);
  void push(std::string_view text);  // UTF-8; may split words anywhere
  void flush();
  // Speaking rate: 1 normal, 0.9 = 10 % slower (durations and pauses).
  void setRate(float rate) { rate_ = rate > 0.1f ? rate : 0.1f; }                      // end of input: say what is pending

  struct Word {
    std::vector<uint8_t> tokens;
    bool accent;  // content word: carries a pitch accent
    std::string text;  // the word as written (lower case)
    bool syllabicN = false;  // -tion: the schwa dropped, the n is the syllable
    uint32_t flaps = 0;      // bit i: token i is a flap (a t or d tapped, "city")
  };

 private:
  void endWord();
  void closeQuote();
  void addWord(const std::string& word);
  bool expandAbbreviation();
  int phraseSyllables() const;
  bool symmetricAt(size_t j) const;  // parallel halves split at word j
  float phraseHash() const;  // after a '.': true if it was not a sentence end
  void addNumber(const std::string& digits);
  void sayPhrase(char end);  // end: '.', '?', ',' (continues) ...
  void pause(int stops);     // silence in 15 ms steps
  std::vector<std::vector<float>> durations() const;  // ms per token (Klatt)
  Synth& synth_;
  std::vector<Word> phrase_;
  std::string lastWord_;  // the word before the current phrase (homograph context)
  bool pointDigits_ = false;  // after a decimal point: digits read one by one
  std::string pending_;  // incomplete UTF-8 sequence from the last push
  int newlines_ = 0;  // consecutive line ends (2: paragraph)
  float rate_ = 1.0f;  // speaking rate (setRate)
  bool sentenceEnd_ = false;  // the phrase being said ends a sentence
  std::deque<std::string> recent_;  // recently accented words (given information)
  std::deque<std::string> recentPhrases_;  // recently said phrases (repetitions build up)
  char lastEnd_ = ' ';  // how the phrase being said ends
  std::string sentenceFirstWord_;  // for wh-questions
  int sentenceInParagraph_ = 0, phraseInSentence_ = 0;  // position, for the melody
  size_t sentenceSyllables_ = 0;  // syllables in the sentence's earlier phrases
  float sentenceMaxAccent_ = -1000;  // highest accent pitch of the sentence so far (st)
  int maxCommaStops_ = 0;  // the longest comma pause of the sentence so far
  int commaRun_ = 0;  // comma phrases since the last sentence or clause end
  size_t deferredSplit_ = 0;  // a long-phrase split waiting at this word index ("and")
  int cannotSentences_ = 0;  // a "cannot" was said in this or the last sentence
  int wordCaps_ = 0;       // capital letters in the word being read
  bool capsWord_ = false;  // the word being added was written in capitals
  bool sentenceEnded_ = false;  // the last mark was . ! ? (a line end then ends a paragraph)
  bool breathBeforeNext_ = false;
  std::vector<std::string> prevPhraseWords_;  // accented words of the sentence's previous phrase
  bool prevPhraseHadNot_ = false;             // ... and whether it had "not"/"never"  // a sentence ended: breathe when the next starts
  bool ordinalNext_ = false;  // the number being read is an ordinal (21st)
  int dollarNext_ = 0;       // a currency sign before the number: 1 $, 2 £, 3 €
  bool centsPence_ = false;   // £3.50: the part after the point is pence
  bool numberJustSaid_ = false, numberWasOne_ = false;  // for a unit or am/pm after it
  bool centsNext_ = false;    // $3.50: the digits after the point are cents
  bool fractionNext_ = false, fractionPlural_ = false;  // 1/2, 2/5: the denominator
  unsigned long numerator_ = 0;
  bool pluralNext_ = false;   // 1990s: the number is a decade
  bool inQuote_ = false;      // inside a quotation (dialogue)
  bool speechTag_ = false;    // the next phrase follows a closed quotation ("said Mum")
  bool flushing_ = false;     // flush(): the held-back last word is read now
  std::string word_;    // letters of the word being read
  std::string digits_;  // digits of the number being read
};

}  // namespace puhuja

#endif  // PUHUJA_ENGLISH_H_
